package com.quincaisoft.audit.application;
import com.quincaisoft.audit.api.*;import com.quincaisoft.audit.infrastructure.*;import com.quincaisoft.shared.*;import jakarta.persistence.*;import org.springframework.stereotype.Service;import java.util.*;import java.time.*;
@Service public class DefaultAuditService implements AuditService {private final EntityManager em;private final ScopedTransactions tx;public DefaultAuditService(EntityManager em,ScopedTransactions tx){this.em=em;this.tx=tx;}
public void append(UUID op,String action,String type,UUID source,String reason){tx.execute(()->{var s=TenantContext.current();if(op==null||source==null||action==null||action.isBlank()||reason==null||reason.isBlank())throw new IllegalArgumentException("Audit identity and reason required");var e=new AuditEvent();e.tenantId=s.tenantId();e.companyId=s.companyId();e.branchId=s.branchId();e.actorId=s.actorId();e.id=UUID.randomUUID();e.operationId=op;e.action=action;e.sourceType=type;e.sourceId=source;e.reason=reason;e.recordedAt=Instant.now();em.persist(e);return null;});}
public List<Event> recent(){return tx.execute(()->em.createQuery("select a from AuditEvent a order by a.recordedAt desc,a.id",AuditEvent.class).setMaxResults(200).getResultList().stream().map(e->new Event(e.id,e.actorId,e.operationId,e.action,e.sourceType,e.sourceId,e.reason,e.recordedAt)).toList());}}